namespace PixelForge {
public sealed class SceneLayer {
    public string Id=Guid.NewGuid().ToString("N"),Name="Слой";
    public double Start=0,Duration=6,Fps=12,X=0,Y=0,Scale=1,Opacity=1,Rotation=0;
    public double EndX=0,EndY=0,EndScale=1,EndOpacity=1,EndRotation=0,FadeIn=0,FadeOut=0;
    public double Brightness=0,EndBrightness=0;
    public bool Locked=false,Solo=false;
    public string LabelColor="#3E527E";
    public int Stabilization=0,PaletteSize=64,ReferenceThreshold=56;
    public bool ProceduralLoop=false;
    public string BackgroundLibraryId;
    public bool Visible=true,Loop=true,Animate=false,Smooth=true;
    public string[] Assets;public string MaskAsset; [ScriptIgnore] public Frame Mask {get;set;}
    [ScriptIgnore] public List<Frame> Frames {get;set;}
    public SceneLayer(){Frames=new List<Frame>();}
    public double Progress(double time){double p=Math.Max(0,Math.Min(1,(time-Start)/Duration));return Smooth?p*p*(3-2*p):p;}
    public Frame At(double time){if(Frames.Count==0||time<Start||time>=Start+Duration)return null;int i=(int)Math.Floor(Math.Max(0,time-Start)*Fps+1e-7);var frames=TemporalStabilizer.Display(this);return LayerMasks.Apply(frames[Loop?i%frames.Count:Math.Min(i,frames.Count-1)],Mask);}
    public double Value(double a,double b,double time){return Animate?a+(b-a)*Progress(time):a;}
    public double Alpha(double time){double a=Value(Opacity,EndOpacity,time);if(FadeIn>0)a*=Math.Min(1,Math.Max(0,(time-Start)/FadeIn));if(FadeOut>0)a*=Math.Min(1,Math.Max(0,(Start+Duration-time)/FadeOut));return Math.Max(0,Math.Min(1,a));}
}
public sealed class Cutscene {
    public int Version=1,Width=640,Height=360,Fps=24;
    public int OutputWidth=0,OutputHeight=0;
    public bool IntegerScale=true;
    public double Duration=6,Crossfade=.5;
    public bool Seamless=false,PixelArt=true;
    public string Background="#172235";
    public List<SceneLayer> Layers=new List<SceneLayer>();
    [ScriptIgnore] public double Overlap {get{return Seamless?Math.Min(Crossfade,Duration/2):0;}}
    [ScriptIgnore] public double ExportDuration {get{return Duration-Overlap;}}
    [ScriptIgnore] public int RenderWidth {get{return OutputWidth==0?Width:OutputWidth;}}
    [ScriptIgnore] public int RenderHeight {get{return OutputHeight==0?Height:OutputHeight;}}
    public void Validate(){
        if(Version!=1||!ValidSize(Width,Height)||!ValidSize(RenderWidth,RenderHeight)||OutputWidth<0||OutputHeight<0||(OutputWidth==0)!=(OutputHeight==0)||Fps<1||Fps>60||!Finite(Duration)||Duration<.1||Duration>120||!Finite(Crossfade)||Crossfade<0||Crossfade>Duration/2)throw new Exception("Холст и экспорт: от 16 px до 3840 px по стороне, до 8.3 млн пикселей (включая 4K и 9:16). FPS 1…60, длительность 0.1…120 с, переход до половины сцены.");
        ColorConverter.ConvertFromString(Background);if(Layers==null||Layers.Count>64)throw new Exception("Не более 64 слоёв.");
        foreach(var l in Layers){if(l==null)throw new Exception("Пустой слой.");if(l.Mask!=null&&l.Frames.Count>0&&(l.Mask.W!=l.Frames[0].W||l.Mask.H!=l.Frames[0].H))throw new Exception("Размер маски не совпадает со слоем.");if(l.Stabilization<0||l.Stabilization>3||l.PaletteSize<16||l.PaletteSize>256||l.ReferenceThreshold<8||l.ReferenceThreshold>128)throw new Exception("Стабилизация: сила 0…3, палитра 16…256.");ColorConverter.ConvertFromString(l.LabelColor);double[] nums={l.Start,l.Duration,l.Fps,l.X,l.Y,l.Scale,l.Opacity,l.Rotation,l.EndX,l.EndY,l.EndScale,l.EndOpacity,l.EndRotation,l.FadeIn,l.FadeOut,l.Brightness,l.EndBrightness};if(nums.Any(v=>!Finite(v))||Math.Abs(l.Brightness)>100||Math.Abs(l.EndBrightness)>100||l.Start<0||l.Start>=Duration||l.Duration<=0||l.Start+l.Duration>Duration+.001||l.Fps<1||l.Fps>60||l.Scale<.01||l.Scale>32||l.EndScale<.01||l.EndScale>32||l.Opacity<0||l.Opacity>1||l.EndOpacity<0||l.EndOpacity>1||l.FadeIn<0||l.FadeOut<0||l.FadeIn+l.FadeOut>l.Duration+.001||Math.Abs(l.X)>100000||Math.Abs(l.Y)>100000||Math.Abs(l.EndX)>100000||Math.Abs(l.EndY)>100000||Math.Abs(l.Rotation)>36000||Math.Abs(l.EndRotation)>36000)throw new Exception("Некорректные параметры слоя «"+l.Name+"». Время слоя должно помещаться в сцену, прозрачность — 0…1, масштаб — 0.01…32, яркость — −100…100.");}
    }
    static bool Finite(double n){return !double.IsNaN(n)&&!double.IsInfinity(n);}
    static bool ValidSize(int w,int h){return w>=16&&h>=16&&w<=3840&&h<=3840&&(long)w*h<=8294400;}
}
public sealed class ResolutionPreset {
    public string Name;public int Width,Height;
    public ResolutionPreset(string name,int width,int height){Name=name;Width=width;Height=height;}
    public override string ToString(){return Name;}
    public static ResolutionPreset[] All(){return new[]{new ResolutionPreset("Свой размер",0,0),new ResolutionPreset("320 × 180 · 16:9",320,180),new ResolutionPreset("640 × 360 · 16:9",640,360),new ResolutionPreset("1280 × 720 · HD",1280,720),new ResolutionPreset("1920 × 1080 · Full HD",1920,1080),new ResolutionPreset("2560 × 1440 · QHD",2560,1440),new ResolutionPreset("3840 × 2160 · 4K",3840,2160),new ResolutionPreset("360 × 640 · 9:16",360,640),new ResolutionPreset("720 × 1280 · 9:16",720,1280),new ResolutionPreset("1080 × 1920 · 9:16",1080,1920),new ResolutionPreset("2160 × 3840 · 9:16",2160,3840),new ResolutionPreset("1080 × 1080 · 1:1",1080,1080),new ResolutionPreset("640 × 480 · 4:3",640,480)};}
}
public static class SceneRenderer {
    static readonly Dictionary<Frame,BitmapSource> cache=new Dictionary<Frame,BitmapSource>();
    static readonly Dictionary<Frame,Dictionary<int,BitmapSource>> brightnessCache=new Dictionary<Frame,Dictionary<int,BitmapSource>>();static long brightPixels;
    public static void ClearCache(){cache.Clear();brightnessCache.Clear();brightPixels=0;}
    static BitmapSource Bitmap(Frame f){BitmapSource b;if(!cache.TryGetValue(f,out b)){b=f.Bitmap();b.Freeze();cache[f]=b;}return b;}
    public static Frame AdjustBrightness(Frame source,double value){var f=source.Clone();double amount=Math.Max(-100,Math.Min(100,value))/100;for(int p=0;p<f.Data.Length;p+=4)for(int c=0;c<3;c++){double v=f.Data[p+c];f.Data[p+c]=(byte)Math.Round(amount>=0?v+(255-v)*amount:v*(1+amount));}return f;}
    static BitmapSource BrightBitmap(Frame f,double value){int key=(int)Math.Round(value*10);if(key==0)return Bitmap(f);Dictionary<int,BitmapSource> entries;BitmapSource image;if(brightnessCache.TryGetValue(f,out entries)&&entries.TryGetValue(key,out image))return image;if(brightPixels+(long)f.W*f.H>16000000){brightnessCache.Clear();brightPixels=0;}if(!brightnessCache.TryGetValue(f,out entries)){entries=new Dictionary<int,BitmapSource>();brightnessCache[f]=entries;}image=AdjustBrightness(f,key/10.0).Bitmap();image.Freeze();entries[key]=image;brightPixels+=(long)f.W*f.H;return image;}
    public static bool LayerVisible(Cutscene scene,SceneLayer layer){return layer.Visible&&(!scene.Layers.Any(l=>l.Solo)||layer.Solo);}
    public static SceneLayer Pick(Cutscene scene,double time,Point point){time=Math.Min(time,scene.Duration-1e-8);foreach(var l in scene.Layers.AsEnumerable().Reverse()){if(l.Locked||!LayerVisible(scene,l)||l.Alpha(time)<=0)continue;var f=l.At(time);if(f==null)continue;double scale=l.Value(l.Scale,l.EndScale,time),cx=f.W*scale/2,cy=f.H*scale/2;double x=point.X-l.Value(l.X,l.EndX,time)-cx,y=point.Y-l.Value(l.Y,l.EndY,time)-cy,a=-l.Value(l.Rotation,l.EndRotation,time)*Math.PI/180;double px=(x*Math.Cos(a)-y*Math.Sin(a)+cx)/scale,py=(x*Math.Sin(a)+y*Math.Cos(a)+cy)/scale;if(px<0||py<0||px>=f.W||py>=f.H)continue;if(f.Data[((int)py*f.W+(int)px)*4+3]>15)return l;}return null;}
    static void DrawAt(DrawingContext dc,Cutscene scene,double time){
        dc.DrawRectangle(new SolidColorBrush((Color)ColorConverter.ConvertFromString(scene.Background)),null,new Rect(0,0,scene.Width,scene.Height));
        foreach(var l in scene.Layers){if(!LayerVisible(scene,l))continue;var f=l.At(time);if(f==null)continue;double scale=l.Value(l.Scale,l.EndScale,time),x=l.Value(l.X,l.EndX,time),y=l.Value(l.Y,l.EndY,time),angle=l.Value(l.Rotation,l.EndRotation,time);
            dc.PushOpacity(l.Alpha(time));dc.PushTransform(new TranslateTransform(x,y));dc.PushTransform(new RotateTransform(angle,f.W*scale/2,f.H*scale/2));var image=new DrawingGroup();RenderOptions.SetBitmapScalingMode(image,scene.PixelArt?BitmapScalingMode.NearestNeighbor:BitmapScalingMode.HighQuality);using(var pixels=image.Open())pixels.DrawImage(BrightBitmap(f,l.Value(l.Brightness,l.EndBrightness,time)),new Rect(0,0,f.W*scale,f.H*scale));dc.DrawDrawing(image);dc.Pop();dc.Pop();dc.Pop();}
    }
    public static void Draw(DrawingContext dc,Cutscene scene,double time){
        dc.PushClip(new RectangleGeometry(new Rect(0,0,scene.Width,scene.Height)));DrawAt(dc,scene,Math.Min(time,scene.Duration-1e-8));
        double overlap=scene.Overlap;
        if(overlap>0&&time>=scene.Duration-overlap){double p=Math.Max(0,Math.Min(1,(time-scene.Duration+overlap)/overlap));p=p*p*(3-2*p);dc.PushOpacity(p);DrawAt(dc,scene,Math.Max(0,time-(scene.Duration-overlap)));dc.Pop();}
        dc.Pop();
    }
    public static Frame Render(Cutscene scene,double time){var v=new DrawingVisual();RenderOptions.SetBitmapScalingMode(v,scene.PixelArt?BitmapScalingMode.NearestNeighbor:BitmapScalingMode.HighQuality);using(var dc=v.RenderOpen())Draw(dc,scene,time);var b=new RenderTargetBitmap(scene.Width,scene.Height,96,96,PixelFormats.Pbgra32);b.Render(v);return Frame.From(b);}
    public static Rect OutputRect(Cutscene scene){double scale=Math.Min(scene.RenderWidth/(double)scene.Width,scene.RenderHeight/(double)scene.Height);if(scene.IntegerScale)scale=scale>=1?Math.Floor(scale):1/Math.Ceiling(1/scale);double w=scene.Width*scale,h=scene.Height*scale;return new Rect(Math.Floor((scene.RenderWidth-w)/2),Math.Floor((scene.RenderHeight-h)/2),w,h);}
    public static Frame RenderOutput(Cutscene scene,double time){
        var source=Render(scene,time);if(scene.RenderWidth==scene.Width&&scene.RenderHeight==scene.Height)return source;
        if(scene.PixelArt){
            var result=new Frame(scene.RenderWidth,scene.RenderHeight);var bg=(Color)ColorConverter.ConvertFromString(scene.Background);for(int p=0;p<result.Data.Length;p+=4){result.Data[p]=bg.B;result.Data[p+1]=bg.G;result.Data[p+2]=bg.R;result.Data[p+3]=bg.A;}
            Rect rect=OutputRect(scene);int left=Math.Max(0,(int)Math.Ceiling(rect.Left)),right=Math.Min(result.W,(int)Math.Ceiling(rect.Right)),top=Math.Max(0,(int)Math.Ceiling(rect.Top)),bottom=Math.Min(result.H,(int)Math.Ceiling(rect.Bottom));
            var map=new int[Math.Max(0,right-left)];for(int x=left;x<right;x++)map[x-left]=Math.Max(0,Math.Min(source.W-1,(int)Math.Floor((x+.5-rect.X)*source.W/rect.Width)))*4;
            int previousY=-1;for(int y=top;y<bottom;y++){int sy=Math.Max(0,Math.Min(source.H-1,(int)Math.Floor((y+.5-rect.Y)*source.H/rect.Height)));int row=(y*result.W+left)*4;if(sy==previousY){Buffer.BlockCopy(result.Data,row-result.W*4,result.Data,row,(right-left)*4);continue;}for(int x=left;x<right;x++){int src=sy*source.W*4+map[x-left],dst=row+(x-left)*4;for(int c=0;c<4;c++)result.Data[dst+c]=source.Data[src+c];}previousY=sy;}
            return result;
        }
        var v=new DrawingVisual();RenderOptions.SetBitmapScalingMode(v,scene.PixelArt?BitmapScalingMode.NearestNeighbor:BitmapScalingMode.HighQuality);RenderOptions.SetEdgeMode(v,EdgeMode.Aliased);
        using(var dc=v.RenderOpen()){dc.DrawRectangle(new SolidColorBrush((Color)ColorConverter.ConvertFromString(scene.Background)),null,new Rect(0,0,scene.RenderWidth,scene.RenderHeight));dc.DrawImage(source.Bitmap(),OutputRect(scene));}
        var b=new RenderTargetBitmap(scene.RenderWidth,scene.RenderHeight,96,96,PixelFormats.Pbgra32);b.Render(v);return Frame.From(b);
    }
}
public static class SceneFile {
    public static void Save(Cutscene scene,string path){
        scene.Validate();string stage=path+".writing-"+Guid.NewGuid().ToString("N");
        try{using(var zip=ZipFile.Open(stage,ZipArchiveMode.Create)){
            for(int n=0;n<scene.Layers.Count;n++){var l=scene.Layers[n];l.Assets=new string[l.Frames.Count];for(int k=0;k<l.Frames.Count;k++){string name="assets/"+n.ToString("D3")+"/"+k.ToString("D4")+".png";l.Assets[k]=name;var e=zip.CreateEntry(name,CompressionLevel.Fastest);using(var s=e.Open())using(var buffer=new MemoryStream()){var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(l.Frames[k].Bitmap()));enc.Save(buffer);buffer.Position=0;buffer.CopyTo(s);}}}
            foreach(var layer in scene.Layers){layer.MaskAsset=null;if(layer.Mask==null)continue;layer.MaskAsset="masks/"+scene.Layers.IndexOf(layer)+".png";using(var stream=zip.CreateEntry(layer.MaskAsset,CompressionLevel.Fastest).Open())using(var buffer=new MemoryStream()){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(layer.Mask.Bitmap()));encoder.Save(buffer);buffer.Position=0;buffer.CopyTo(stream);}}
            using(var w=new StreamWriter(zip.CreateEntry("scene.json").Open(),new UTF8Encoding(false)))w.Write(new JavaScriptSerializer().Serialize(scene));
        }if(File.Exists(path))File.Replace(stage,path,null);else File.Move(stage,path);}finally{if(File.Exists(stage))File.Delete(stage);}
    }
    public static Cutscene Load(string path){
        using(var zip=ZipFile.OpenRead(path)){var manifest=zip.GetEntry("scene.json");if(manifest==null||manifest.Length>2000000)throw new Exception("В проекте отсутствует корректный scene.json.");Cutscene scene;using(var r=new StreamReader(manifest.Open()))scene=new JavaScriptSerializer().Deserialize<Cutscene>(r.ReadToEnd());if(scene==null)throw new Exception("Проект пуст.");scene.Validate();long pixels=0;
            foreach(var l in scene.Layers){if(l.Assets==null||l.Assets.Length<1||l.Assets.Length>240)throw new Exception("Слой должен содержать 1…240 кадров.");l.Frames=new List<Frame>();foreach(var asset in l.Assets){if(asset==null||!asset.StartsWith("assets/",StringComparison.Ordinal)||asset.Contains(".."))throw new Exception("Некорректная ссылка на ресурс.");var e=zip.GetEntry(asset);if(e==null||e.Length>64000000)throw new Exception("Ресурс отсутствует или слишком большой.");using(var s=e.Open())using(var buffer=new MemoryStream()){s.CopyTo(buffer);buffer.Position=0;var b=BitmapFrame.Create(buffer,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);pixels+=(long)b.PixelWidth*b.PixelHeight;if(pixels>64000000)throw new Exception("Проект превышает 64 млн пикселей ресурсов.");if(l.Frames.Count>0&&(b.PixelWidth!=l.Frames[0].W||b.PixelHeight!=l.Frames[0].H))throw new Exception("Кадры слоя имеют разные размеры.");l.Frames.Add(Frame.From(b));}}}foreach(var layer in scene.Layers){if(layer.MaskAsset==null)continue;if(!layer.MaskAsset.StartsWith("masks/",StringComparison.Ordinal)||layer.MaskAsset.Contains(".."))throw new Exception("Некорректная маска слоя.");var maskEntry=zip.GetEntry(layer.MaskAsset);if(maskEntry==null||maskEntry.Length>64000000)throw new Exception("Нет ресурса маски.");using(var stream=maskEntry.Open())using(var buffer=new MemoryStream()){stream.CopyTo(buffer);buffer.Position=0;var bitmap=BitmapFrame.Create(buffer,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);if(bitmap.PixelWidth!=layer.Frames[0].W||bitmap.PixelHeight!=layer.Frames[0].H)throw new Exception("Размер маски не совпадает со слоем.");layer.Mask=Frame.From(bitmap);}}return scene;}
    }
}
public sealed class SceneView : FrameworkElement {
    public Cutscene Scene;public SceneLayer Selected;public double Time;public Action<double,double> MoveSelected;public Action MoveStarted,MoveFinished;public Action<SceneLayer> SelectLayer;
    public double Zoom=0,PanX=0,PanY=0;public Action ZoomChanged;
    Point start,panStart;double sx,sy,panOriginX,panOriginY;bool dragging,panning,moveRecorded;
    public void SetZoom(double zoom){Zoom=zoom;PanX=PanY=0;InvalidateVisual();if(ZoomChanged!=null)ZoomChanged();}
    public void ZoomBy(double factor,Point anchor){if(Scene==null)return;var old=Bounds();double z=old.Width/Scene.Width;double x=(anchor.X-old.X)/z,y=(anchor.Y-old.Y)/z;Zoom=Math.Max(.025,Math.Min(32,z*factor));PanX=anchor.X-ActualWidth/2-(x-Scene.Width/2.0)*Zoom;PanY=anchor.Y-ActualHeight/2-(y-Scene.Height/2.0)*Zoom;InvalidateVisual();if(ZoomChanged!=null)ZoomChanged();}
    public SceneView(){ClipToBounds=true;ToolTip="Колесо — масштаб; средняя кнопка мыши — перемещение холста. Масштаб просмотра не меняет экспорт.";
        MouseWheel+=(s,e)=>{ZoomBy(e.Delta>0?1.25:.8,e.GetPosition(this));e.Handled=true;};
        MouseDown+=(s,e)=>{if(e.ChangedButton!=MouseButton.Middle)return;panning=true;panStart=e.GetPosition(this);panOriginX=PanX;panOriginY=PanY;CaptureMouse();Cursor=Cursors.ScrollAll;e.Handled=true;};
        MouseUp+=(s,e)=>{if(e.ChangedButton==MouseButton.Middle){panning=false;Cursor=Cursors.Arrow;if(IsMouseCaptured)ReleaseMouseCapture();}};
        MouseLeftButtonDown+=(s,e)=>{if(panning||Scene==null)return;var p=e.GetPosition(this);var rect=Bounds();double z=rect.Width/Scene.Width;var hit=SceneRenderer.Pick(Scene,Time,new Point((p.X-rect.X)/z,(p.Y-rect.Y)/z));if(SelectLayer!=null)SelectLayer(hit);if(hit==null||hit.Locked)return;Selected=hit;start=p;sx=Selected.X;sy=Selected.Y;dragging=true;moveRecorded=false;CaptureMouse();};
        MouseMove+=(s,e)=>{if(!IsMouseCaptured)return;var p=e.GetPosition(this);if(panning){PanX=panOriginX+p.X-panStart.X;PanY=panOriginY+p.Y-panStart.Y;InvalidateVisual();return;}if(!dragging||Selected==null||Selected.Locked)return;if(!moveRecorded){if(Math.Abs(p.X-start.X)+Math.Abs(p.Y-start.Y)<2)return;if(MoveStarted!=null)MoveStarted();moveRecorded=true;}double z=Bounds().Width/Scene.Width;if(MoveSelected!=null)MoveSelected(sx+(p.X-start.X)/z,sy+(p.Y-start.Y)/z);};MouseLeftButtonUp+=(s,e)=>EndDrag();LostMouseCapture+=(s,e)=>{panning=false;Cursor=Cursors.Arrow;EndDrag();};}
    void EndDrag(){bool was=dragging&&moveRecorded;dragging=moveRecorded=false;if(IsMouseCaptured)ReleaseMouseCapture();if(was&&MoveFinished!=null)MoveFinished();}
    Rect Bounds(){double z=Zoom>0?Zoom:Math.Max(.001,Math.Min(Math.Max(1,ActualWidth-32)/Scene.Width,Math.Max(1,ActualHeight-32)/Scene.Height));return new Rect((ActualWidth-Scene.Width*z)/2+PanX,(ActualHeight-Scene.Height*z)/2+PanY,Scene.Width*z,Scene.Height*z);}
    protected override void OnRender(DrawingContext dc){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(14,18,27)),null,new Rect(0,0,ActualWidth,ActualHeight));if(Scene==null)return;Rect r=Bounds();dc.PushClip(new RectangleGeometry(r));dc.PushTransform(new TranslateTransform(r.X,r.Y));double z=r.Width/Scene.Width;dc.PushTransform(new ScaleTransform(z,z));RenderOptions.SetBitmapScalingMode(this,Scene.PixelArt?BitmapScalingMode.NearestNeighbor:BitmapScalingMode.HighQuality);SceneRenderer.Draw(dc,Scene,Time);
        if(Selected!=null&&SceneRenderer.LayerVisible(Scene,Selected)&&Selected.At(Time)!=null){var f=Selected.At(Time);double scale=Selected.Value(Selected.Scale,Selected.EndScale,Time),x=Selected.Value(Selected.X,Selected.EndX,Time),y=Selected.Value(Selected.Y,Selected.EndY,Time);dc.PushTransform(new RotateTransform(Selected.Value(Selected.Rotation,Selected.EndRotation,Time),x+f.W*scale/2,y+f.H*scale/2));dc.DrawRectangle(null,new Pen(Selected.Locked?Brushes.SlateGray:Brushes.MediumAquamarine,1.5/z),new Rect(x,y,f.W*scale,f.H*scale));dc.Pop();}dc.Pop();dc.Pop();dc.Pop();}
}
public sealed class SceneTimeline : FrameworkElement {
    public Cutscene Scene;public SceneLayer Selected;public double Time;public Action<double> Seek;public Action<SceneLayer> Select;public Action<SceneLayer,string> ToggleFlag;public Action Changed;public Action DragStarted,DragFinished;
    const double LabelWidth=210,Header=28,Row=34;SceneLayer drag;double startMouse,startTime,startDuration;bool resize,dragRecorded;
    public SceneTimeline(){MinHeight=130;MouseLeftButtonDown+=Down;MouseMove+=Move;MouseLeftButtonUp+=(s,e)=>EndDrag();LostMouseCapture+=(s,e)=>EndDrag();}
    double TrackWidth {get{return Math.Max(20,ActualWidth-LabelWidth-12);}}
    double ToTime(double x){return Math.Max(0,Math.Min(Scene.Duration,(x-LabelWidth)/TrackWidth*Scene.Duration));}
    static void Text(DrawingContext dc,string value,double x,double y,double size,Brush color,double maxWidth){var f=new FormattedText(value,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,color);f.MaxTextWidth=Math.Max(1,maxWidth);f.MaxLineCount=1;f.Trimming=TextTrimming.CharacterEllipsis;dc.DrawText(f,new Point(x,y));}
    protected override void OnRender(DrawingContext dc){if(Scene==null)return;dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(26,33,47)),null,new Rect(0,0,ActualWidth,ActualHeight));int steps=Math.Max(2,Math.Min(12,(int)(TrackWidth/75)));for(int n=0;n<=steps;n++){double t=Scene.Duration*n/steps,x=LabelWidth+TrackWidth*n/steps;dc.DrawLine(new Pen(new SolidColorBrush(Color.FromRgb(52,64,84)),1),new Point(x,0),new Point(x,ActualHeight));Text(dc,t.ToString("0.##")+"s",Math.Min(x+3,ActualWidth-45),4,11,Brushes.LightSlateGray,70);}
