public static class SceneExport {
    public static string Encoder {get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tools","ffmpeg.exe");}}
    static string Quote(string path){if(path.IndexOf('"')>=0)throw new Exception("Некорректный путь.");return "\""+path+"\"";}
    public static async Task<string> Run(string args,CancellationToken token){
        using(var p=new Process()){p.StartInfo=new ProcessStartInfo(Encoder,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};p.Start();var error=p.StandardError.ReadToEndAsync();using(token.Register(()=>{try{if(!p.HasExited)p.Kill();}catch{}})){await Task.Run(()=>p.WaitForExit());token.ThrowIfCancellationRequested();string log=await error;if(p.ExitCode!=0)throw new Exception("FFmpeg: "+log.Substring(Math.Max(0,log.Length-1600)));return log;}}
    }
    public static async Task Encode(Cutscene scene,string path,bool gif,Action<int,int> progress,CancellationToken token){
        scene.Validate();await TemporalStabilizer.PrepareScene(scene,token);if(!File.Exists(Encoder))throw new Exception("Не найден tools/ffmpeg.exe.");if(!gif&&(scene.RenderWidth%2!=0||scene.RenderHeight%2!=0))throw new Exception("Для MP4 задайте чётные ширину и высоту экспорта.");
        int n=Math.Max(1,(int)Math.Ceiling(scene.ExportDuration*scene.Fps-1e-8));
        string root=Path.GetFullPath(Path.GetTempPath()),temp=Path.Combine(root,"PixelForgeRender_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
        string stage=Path.Combine(temp,gif?"frames.mkv":"result.mp4"),result=gif?Path.Combine(temp,"result.gif"):stage;
        try{
            string args="-hide_banner -loglevel error -y -f rawvideo -pixel_format bgra -video_size "+scene.RenderWidth+"x"+scene.RenderHeight+" -framerate "+scene.Fps+" -i pipe:0 -an "+(gif?"-c:v ffv1 ":"-c:v libx264 -preset medium -crf 16 -pix_fmt yuv420p -movflags +faststart ")+Quote(stage);
            using(var p=new Process()){p.StartInfo=new ProcessStartInfo(Encoder,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true};p.Start();var error=p.StandardError.ReadToEndAsync();using(token.Register(()=>{try{if(!p.HasExited)p.Kill();}catch{}})){
                try{for(int i=0;i<n;i++){token.ThrowIfCancellationRequested();var f=SceneRenderer.RenderOutput(scene,scene.Overlap+i/(double)scene.Fps);await p.StandardInput.BaseStream.WriteAsync(f.Data,0,f.Data.Length,token);progress(i+1,n);await Task.Delay(1,token);}p.StandardInput.Close();await Task.Run(()=>p.WaitForExit());token.ThrowIfCancellationRequested();string log=await error;if(p.ExitCode!=0)throw new Exception("FFmpeg: "+log);}finally{try{if(!p.HasExited){p.Kill();p.WaitForExit(3000);}}catch{}}}}
            if(gif){progress(n,n);string palette=Path.Combine(temp,"palette.png");await Run("-hide_banner -loglevel error -y -i "+Quote(stage)+" -vf palettegen=reserve_transparent=0 -frames:v 1 "+Quote(palette),token);await Run("-hide_banner -loglevel error -y -i "+Quote(stage)+" -i "+Quote(palette)+" -lavfi paletteuse=dither=none -loop "+(scene.Seamless?"0":"-1")+" "+Quote(result),token);}
            token.ThrowIfCancellationRequested();string delivery=path+".writing-"+Guid.NewGuid().ToString("N");try{File.Copy(result,delivery);if(File.Exists(path))File.Replace(delivery,path,null);else File.Move(delivery,path);}finally{if(File.Exists(delivery))File.Delete(delivery);}
        }finally{if(Path.GetDirectoryName(Path.GetFullPath(temp)).TrimEnd(Path.DirectorySeparatorChar).Equals(root.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(temp).StartsWith("PixelForgeRender_",StringComparison.Ordinal)&&Directory.Exists(temp))Directory.Delete(temp,true);}
    }
}
