    void Remember(){EndLiveEdit();PushHistory(Clone(scene));dirty=true;}
    void Undo(){Stop();EndLiveEdit();if(history.Count==0)return;string id=selected==null?null:selected.Id;scene=history.Pop();selected=scene.Layers.FirstOrDefault(l=>l.Id==id)??scene.Layers.LastOrDefault();time=Math.Min(time,scene.Duration);dirty=true;ShowProject();ShowLayer();RefreshLayers();RefreshView();Tell("Последнее изменение сцены отменено.");if(WorkspaceEdited!=null)WorkspaceEdited();}
    void Select(SceneLayer layer){EndLiveEdit();selected=layer;ShowLayer();RefreshView();}
    void RefreshLayers(){SceneRenderer.ClearCache();updating=true;ClearInlineNames();layers.Items.Clear();foreach(var l in scene.Layers.AsEnumerable().Reverse()){var item=BuildLayerItem(l);layers.Items.Add(item);if(l==selected)layers.SelectedItem=item;}updating=false;timeline.Scene=scene;timeline.Selected=selected;timeline.Refresh();}
    void RefreshView(){view.Scene=scene;view.Selected=selected;view.Time=time;view.InvalidateVisual();timeline.Scene=scene;timeline.Selected=selected;timeline.Time=time;timeline.InvalidateVisual();updating=true;scrub.Maximum=scene.Duration;scrub.Value=time;updating=false;clockText.Text=time.ToString("0.00")+" / "+scene.Duration.ToString("0.00")+" с · "+scene.Width+" × "+scene.Height+(scene.RenderWidth!=scene.Width||scene.RenderHeight!=scene.Height?" → "+scene.RenderWidth+" × "+scene.RenderHeight:"")+" · "+scene.Fps+" fps";}
    public void Stop(){clock.Stop();watch.Stop();}
    void Seek(double t){Stop();time=Math.Max(0,Math.Min(scene.Duration,t));RefreshView();}
    void Play(){if(clock.IsEnabled){Stop();return;}if(time>=scene.Duration)time=scene.Overlap;playStart=time;watch.Restart();clock.Start();}
    static int PresetIndex(ComboBox box,int w,int h){for(int n=1;n<box.Items.Count;n++){var p=(ResolutionPreset)box.Items[n];if(p.Width==w&&p.Height==h)return n;}return 0;}
    void OutputFieldsEnabled(){projectFields["OutputWidth"].IsEnabled=projectFields["OutputHeight"].IsEnabled=followCanvas.IsChecked!=true;}
    void ShowProject(){bool wasUpdating=updating;updating=true;Set(projectFields,"Width",scene.Width);Set(projectFields,"Height",scene.Height);Set(projectFields,"OutputWidth",scene.RenderWidth);Set(projectFields,"OutputHeight",scene.RenderHeight);followCanvas.IsChecked=scene.OutputWidth==0;integerScale.IsChecked=scene.IntegerScale;canvasPreset.SelectedIndex=PresetIndex(canvasPreset,scene.Width,scene.Height);outputPreset.SelectedIndex=scene.OutputWidth==0?0:PresetIndex(outputPreset,scene.RenderWidth,scene.RenderHeight);OutputFieldsEnabled();Set(projectFields,"Fps",scene.Fps);Set(projectFields,"Duration",scene.Duration);projectFields["Background"].Text=scene.Background;Set(projectFields,"Crossfade",scene.Crossfade);pixel.IsChecked=scene.PixelArt;seamless.IsChecked=scene.Seamless;updating=wasUpdating;}
    void ShowLayer(){SyncLayerInspector();}
    public static void ScaleCanvasLayers(Cutscene target,int oldWidth,int oldHeight){double scale=Math.Min(target.Width/(double)oldWidth,target.Height/(double)oldHeight),dx=(target.Width-oldWidth*scale)/2,dy=(target.Height-oldHeight*scale)/2;foreach(var l in target.Layers){l.X=dx+l.X*scale;l.EndX=dx+l.EndX*scale;l.Y=dy+l.Y*scale;l.EndY=dy+l.EndY*scale;l.Scale*=scale;l.EndScale*=scale;}}
    void ApplyProject(){Stop();var next=Clone(scene);next.Width=Integer(projectFields,"Width");next.Height=Integer(projectFields,"Height");next.OutputWidth=followCanvas.IsChecked==true?0:Integer(projectFields,"OutputWidth");next.OutputHeight=followCanvas.IsChecked==true?0:Integer(projectFields,"OutputHeight");next.IntegerScale=integerScale.IsChecked==true;next.Fps=Integer(projectFields,"Fps");next.Duration=Number(projectFields,"Duration");next.Background=projectFields["Background"].Text;next.Crossfade=Number(projectFields,"Crossfade");next.Seamless=seamless.IsChecked==true;next.PixelArt=pixel.IsChecked==true;if(resizeLayers.IsChecked==true&&(next.Width!=scene.Width||next.Height!=scene.Height))ScaleCanvasLayers(next,scene.Width,scene.Height);next.Validate();Remember();string id=selected==null?null:selected.Id;bool resized=scene.Width!=next.Width||scene.Height!=next.Height;scene=next;selected=scene.Layers.FirstOrDefault(l=>l.Id==id);time=Math.Min(time,scene.Duration);ShowProject();ShowLayer();RefreshLayers();RefreshView();if(resized)view.SetZoom(0);Tell("Холст "+scene.Width+" × "+scene.Height+"; экспорт "+scene.RenderWidth+" × "+scene.RenderHeight+"; цикл "+scene.ExportDuration.ToString("0.###")+" с.");}
    void ApplyLayer(){if(selected==null)throw new Exception("Сначала выберите слой.");if(selected.Locked)throw new Exception("Сначала разблокируйте слой.");Stop();var next=Clone(scene);int index=scene.Layers.IndexOf(selected);var l=next.Layers[index];l.Name=layerFields["Name"].Text.Trim();if(l.Name.Length==0)l.Name="Слой";foreach(string name in new[]{"Start","Duration","Fps","X","Y","Scale","Opacity","Rotation","EndX","EndY","EndScale","EndOpacity","EndRotation","FadeIn","FadeOut","Brightness","EndBrightness"})typeof(SceneLayer).GetField(name).SetValue(l,Number(layerFields,name));l.Visible=visible.IsChecked==true;l.Loop=loopLayer.IsChecked==true;l.Animate=animate.IsChecked==true;l.Smooth=smooth.IsChecked==true;next.Validate();Remember();scene=next;selected=l;RefreshLayers();RefreshView();Tell("Свойства слоя применены.");}
    public void AddSequence(List<Frame> input,string name,double fps){
        if(exporting)throw new Exception("Дождитесь завершения экспорта.");if(input==null||input.Count==0||input.Count>240)throw new Exception("Добавьте 1…240 кадров.");if(scene.Layers.Count>=64)throw new Exception("Лимит — 64 слоя.");long total=scene.Layers.Sum(l=>l.Frames.Sum(f=>(long)f.W*f.H))+input.Sum(f=>(long)f.W*f.H);if(total>64000000)throw new Exception("Лимит ресурсов сцены — 64 млн пикселей.");if(input.Any(f=>f.W!=input[0].W||f.H!=input[0].H))throw new Exception("Кадры анимации должны иметь одинаковый холст.");
        Stop();Remember();double scale=Math.Min(1,Math.Min(scene.Width/(double)input[0].W,scene.Height/(double)input[0].H));var layer=new SceneLayer {Name=name,Frames=input.Select(f=>f.Clone()).ToList(),Duration=scene.Duration,Fps=Math.Max(1,Math.Min(60,fps)),Scale=scale,EndScale=scale};layer.X=layer.EndX=(scene.Width-input[0].W*scale)/2;layer.Y=layer.EndY=(scene.Height-input[0].H*scale)/2;scene.Layers.Add(layer);selected=layer;RefreshLayers();ShowLayer();RefreshView();Tell("Добавлен слой «"+name+"». Положение, движение и время — во вкладке «Свойства».");}
    void Import(bool sequence){var d=new OpenFileDialog {Filter="Изображения|*.png;*.jpg;*.jpeg;*.bmp",Multiselect=sequence};if(d.ShowDialog()!=true)return;if(d.FileNames.Length>240)throw new Exception("Максимум 240 кадров в слое.");var input=new List<Frame>();long total=0;foreach(string path in d.FileNames.OrderBy(p=>p,StringComparer.OrdinalIgnoreCase)){var f=Frame.Load(path);total+=(long)f.W*f.H;if(total>32000000)throw new Exception("Импорт превышает 32 млн пикселей.");input.Add(f);}AddSequence(input,Path.GetFileNameWithoutExtension(d.FileNames[0]),scene.Fps);}
    void Reorder(int delta){if(selected==null)return;if(selected.Locked)throw new Exception("Сначала разблокируйте слой.");int n=scene.Layers.IndexOf(selected),target=n+delta;if(target<0||target>=scene.Layers.Count)return;Remember();scene.Layers.RemoveAt(n);scene.Layers.Insert(target,selected);RefreshLayers();RefreshView();}
    void Delete(){if(selected==null)return;if(selected.Locked)throw new Exception("Сначала разблокируйте слой.");Remember();scene.Layers.Remove(selected);selected=scene.Layers.LastOrDefault();RefreshLayers();ShowLayer();RefreshView();}
    void Duplicate(){if(selected==null)return;if(scene.Layers.Count>=64)throw new Exception("Лимит — 64 слоя.");if(scene.Layers.Sum(l=>l.Frames.Sum(f=>(long)f.W*f.H))+selected.Frames.Sum(f=>(long)f.W*f.H)>64000000)throw new Exception("Лимит ресурсов — 64 млн пикселей.");Remember();var next=Clone(scene).Layers[scene.Layers.IndexOf(selected)];next.Id=Guid.NewGuid().ToString("N");next.Name+=" копия";scene.Layers.Insert(scene.Layers.IndexOf(selected)+1,next);selected=next;RefreshLayers();ShowLayer();RefreshView();}
    bool Save(){Stop();EndLiveEdit();var d=new SaveFileDialog {Filter="Катсцена PixelForge|*.cutscene",FileName=projectPath??"scene.cutscene"};if(d.ShowDialog()!=true)return false;SceneFile.Save(scene,d.FileName);projectPath=d.FileName;dirty=false;Tell("Сцена и ресурсы сохранены: "+d.FileName);return true;}
    public bool MayClose(){if(exporting){MessageBox.Show("Сначала завершите или отмените экспорт катсцены.","PixelForge");return false;}if(!dirty)return true;var result=MessageBox.Show("Сохранить изменения катсцены?","PixelForge",MessageBoxButton.YesNoCancel);if(result==MessageBoxResult.Cancel)return false;if(result==MessageBoxResult.No)return true;try{return Save();}catch(Exception ex){Tell(ex.Message);return false;}}
