    void Load(){Stop();if(!MayClose())return;var d=new OpenFileDialog {Filter="Катсцена PixelForge|*.cutscene"};if(d.ShowDialog()!=true)return;var next=SceneFile.Load(d.FileName);scene=next;projectPath=d.FileName;history.Clear();SceneRenderer.ClearCache();selected=scene.Layers.LastOrDefault();time=0;dirty=false;ShowProject();ShowLayer();RefreshLayers();RefreshView();Tell("Сцена открыта вместе со всеми ресурсами.");if(WorkspaceEdited!=null)WorkspaceEdited();}
    async Task Export(bool gif){Stop();EndLiveEdit();try{scene.Validate();var d=new SaveFileDialog {Filter=gif?"GIF|*.gif":"MP4|*.mp4",FileName=gif?"cutscene.gif":"cutscene.mp4"};if(d.ShowDialog()!=true)return;exporting=true;middle.IsEnabled=false;timeline.IsEnabled=false;scrub.IsEnabled=false;cancellation=new CancellationTokenSource();await SceneExport.Encode(scene,d.FileName,gif,(i,n)=>Tell("Рендер "+i+" / "+n+(gif&&i==n?" · сборка палитры GIF…":"…")),cancellation.Token);Tell("Экспорт готов: "+d.FileName);}catch(OperationCanceledException){Tell("Экспорт отменён. Проект сохранён в памяти.");}catch(Exception ex){Tell("Экспорт: "+ex.Message);}finally{exporting=false;middle.IsEnabled=true;timeline.IsEnabled=true;scrub.IsEnabled=true;if(cancellation!=null){cancellation.Dispose();cancellation=null;}}}
