    public void Demo(){
        Stop();Remember();scene=new Cutscene {Width=320,Height=180,Duration=4,Fps=20,Background="#182139",Seamless=true,Crossfade=.5};
        var bg=Paint(320,180,(x,y)=>y<112?Color.FromRgb((byte)(26+y/8),35,(byte)(65+y/5)):Color.FromRgb(38,57,48));var ground=Paint(320,48,(x,y)=>y<8?Color.FromRgb(63,103,66):Color.FromRgb(49,69,52));
        scene.Layers.Add(new SceneLayer {Name="Ночное небо",Duration=4,Frames=new List<Frame>{bg}});scene.Layers.Add(new SceneLayer {Name="Земля",Duration=4,Y=132,EndY=132,Frames=new List<Frame>{ground}});
        var grass=Paint(320,24,(x,y)=>(x%17<3&&y>Math.Abs(x%17-1)*3)?Color.FromRgb(78,128,74):Colors.Transparent);scene.Layers.Add(new SceneLayer {Name="Трава переднего плана",Duration=4,Y=148,EndY=148,Frames=new List<Frame>{grass},Animate=true,EndX=-8,Smooth=true});
        var walker=new List<Frame>();for(int n=0;n<4;n++){int step=n<2?n*2:(3-n)*2;walker.Add(Paint(24,40,(x,y)=>{if(x>=8&&x<16&&y>=3&&y<13)return Color.FromRgb(237,182,123);if(x>=6&&x<18&&y>=14&&y<28)return Color.FromRgb(111,146,220);if(y>=28&&y<38&&((x>=7-step&&x<11-step)||(x>=14+step&&x<18+step)))return Color.FromRgb(29,33,51);return Colors.Transparent;}));}
        var actor=new SceneLayer {Name="Персонаж · ходьба",Duration=4,Fps=8,X=40,Y=103,EndX=230,EndY=103,Frames=walker,Animate=true,Smooth=false};scene.Layers.Insert(2,actor);selected=actor;time=0;projectPath=null;ShowProject();ShowLayer();RefreshLayers();RefreshView();Tell("Демо: 4 слоя, PNG-анимация, движение и плавный цикл. Можно переставлять слои и экспортировать.");
    }
    static Frame Paint(int w,int h,Func<int,int,Color> color){var f=new Frame(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=color(x,y);int p=(y*w+x)*4;f.Data[p]=c.B;f.Data[p+1]=c.G;f.Data[p+2]=c.R;f.Data[p+3]=c.A;}return f;}
